   optionNotes:{A:{why:"The route exists.",cause:"Doubting the match."},B:{why:"200 and application/json."},C:{why:"JSON is not JavaScript.",cause:"Confusing JSON with JS."},D:{why:"Wrong on both counts.",cause:"Guessing."}},
