   optionNotes:{A:{why:"No `id` parameter: POST fails and GET is not allowed.",cause:"Thinking `id` is visible anyway."},B:{why:"GET with the URL's id."},C:{why:"The URL's id has nowhere to go: 500.",cause:"Forgetting placeholders are passed."},D:{why:"POST with the URL's id also searches correctly."}},
   other:"one practical method",verify:"Ran each option in place of the placeholder: B (GET) and D (POST) return `2, pens, 61` for id 2; A and C fail.",asserts:["Trest-api-13"],
